/// <summary>
/// Base data contract for DMF parameters
/// </summary>
[DataContract]
class OMGInboundHandlerDataContract_DMF
{
    OMGDMFImportDefinitionGroup         definitionGroupName;
    OMGDMFDefinitionGroupEntityName     entityName;
}

Method.Source:
/// <summary>
/// The class id for the corresponding validator class
/// </summary>
/// <returns>The class id</returns>
public ClassId validationClassId()
{
    return classNum(OMGContractValidator_DMF);
}

[DataMember, OMGDMFDefinitionGroupAttribute]
public OMGDMFImportDefinitionGroup parmDefinitionGroupName(OMGDMFImportDefinitionGroup _definitionGroupName = definitionGroupName)
{
    definitionGroupName = _definitionGroupName;

    return definitionGroupName;
}

[DataMember, OMGDMFDefinitionGroupEntityAttribute]
public OMGDMFDefinitionGroupEntityName parmEntityName(OMGDMFDefinitionGroupEntityName _entityName = entityName)
{
    entityName = _entityName;

    return entityName;
}

/// <summary>
/// Validates the contract values
/// </summary>
/// <returns>True if ok</returns>
public boolean validate()
{
    return OMGContractValidator_DMF::newValidation(this).validate();
}
